create table if not exists promotion_coupon (id bigint generated by default as identity primary key, name varchar(120) not null, code varchar(64) not null unique, threshold_amount numeric(18,2) not null default 0, discount_amount numeric(18,2) not null, total_quantity integer not null default 0, issued_quantity integer not null default 0, per_user_limit integer not null default 1, starts_at timestamptz not null, ends_at timestamptz not null, enabled boolean not null default true);
create table if not exists promotion_user_coupon (id bigint generated by default as identity primary key, coupon_id bigint not null references promotion_coupon(id) on delete restrict, user_id bigint not null references sys_user(id) on delete cascade, order_id bigint references mall_order(id) on delete set null, status varchar(20) not null default 'AVAILABLE', received_at timestamptz not null default now());
create index if not exists ix_user_coupon_user_status on promotion_user_coupon(user_id, status);
create table if not exists promotion_member_price (id bigint generated by default as identity primary key, user_id bigint not null references sys_user(id) on delete cascade, sku_id bigint not null references mall_product_sku(id) on delete cascade, price numeric(18,2) not null, starts_at timestamptz not null, ends_at timestamptz not null, enabled boolean not null default true);
create table if not exists promotion_points_account (user_id bigint primary key references sys_user(id) on delete cascade, balance integer not null default 0, updated_at timestamptz not null default now());
create table if not exists promotion_points_transaction (id bigint generated by default as identity primary key, user_id bigint not null references sys_user(id) on delete cascade, amount integer not null, balance_after integer not null, type varchar(30) not null, order_id bigint references mall_order(id) on delete set null, created_at timestamptz not null default now());
create table if not exists promotion_full_reduction_rule (id bigint generated by default as identity primary key, threshold_amount numeric(18,2) not null, reduction_amount numeric(18,2) not null, product_id bigint references mall_product(id) on delete set null, enabled boolean not null default true);
create table if not exists promotion_bargain_activity (id bigint generated by default as identity primary key, product_id bigint not null references mall_product(id) on delete restrict, sku_id bigint not null references mall_product_sku(id) on delete restrict, original_price numeric(18,2) not null, lowest_price numeric(18,2) not null, step_amount numeric(18,2) not null, required_helpers integer not null, starts_at timestamptz not null, ends_at timestamptz not null, enabled boolean not null default true);
create table if not exists promotion_bargain_record (id bigint generated by default as identity primary key, activity_id bigint not null references promotion_bargain_activity(id) on delete cascade, user_id bigint not null references sys_user(id) on delete cascade, current_price numeric(18,2) not null, helper_count integer not null default 0, status varchar(20) not null default 'ONGOING', created_at timestamptz not null default now(), expires_at timestamptz not null, unique(activity_id, user_id));
create table if not exists promotion_presale_activity (id bigint generated by default as identity primary key, product_id bigint not null references mall_product(id) on delete restrict, sku_id bigint not null references mall_product_sku(id) on delete restrict, deposit_amount numeric(18,2) not null, final_amount numeric(18,2) not null, delivery_at timestamptz not null, starts_at timestamptz not null, ends_at timestamptz not null, enabled boolean not null default true);
create table if not exists promotion_gift_rule (id bigint generated by default as identity primary key, product_id bigint references mall_product(id) on delete set null, gift_product_id bigint not null references mall_product(id) on delete restrict, gift_sku_id bigint not null references mall_product_sku(id) on delete restrict, threshold_quantity integer not null default 1, gift_quantity integer not null default 1, enabled boolean not null default true);
create table if not exists promotion_limited_discount (id bigint generated by default as identity primary key, product_id bigint not null references mall_product(id) on delete restrict, sku_id bigint not null references mall_product_sku(id) on delete restrict, discount_price numeric(18,2) not null, starts_at timestamptz not null, ends_at timestamptz not null, enabled boolean not null default true);
create table if not exists promotion_order (id bigint generated by default as identity primary key, order_id bigint not null references mall_order(id) on delete cascade, user_id bigint not null references sys_user(id) on delete cascade, type varchar(30) not null, activity_id bigint, status varchar(20) not null default 'Pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(order_id, type));
